        crypto::parse_audit_log(&log_json).map_err(|e| DisasterRecoveryError::InvalidAuditLog {
            message: format!("failed to parse audit log: {e}"),
        })?;
    let current =
        latest_full_state(&audit_log).map_err(|e| DisasterRecoveryError::InvalidAuditLog {
            message: e.to_string(),
        })?;

